#!/usr/bin/env python3
"""
Global Intentional Homicide Trends Report Generator
Analyzes UNODC homicide data and produces a comprehensive HTML report.
"""

import csv
import json
from collections import defaultdict
from statistics import median, mean

# Load data
data = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        row['year'] = int(row['year'])
        row['homicide_rate'] = float(row['homicide_rate'])
        data.append(row)

print(f"Loaded {len(data)} rows")

# Filter helpers
def filter_data(rows, **kwargs):
    result = rows
    for key, val in kwargs.items():
        if val is not None:
            result = [r for r in result if r[key] == val]
    return result

# Get all years
all_years = sorted(set(r['year'] for r in data))
print(f"Years: {min(all_years)} - {max(all_years)}")

# Get all countries
all_countries = sorted(set(r['country'] for r in data))
print(f"Countries: {len(all_countries)}")

# Filter for sex=both and age_group=ALL for main analysis
main_data = [r for r in data if r['sex'] == 'both' and r['age_group'] == 'ALL']
print(f"Main data rows (both/ALL): {len(main_data)}")

# ==============================================================================
# GLOBAL OVERVIEW - Year-by-year statistics
# ==============================================================================

years_data = defaultdict(list)
for r in main_data:
    years_data[r['year']].append(r)

year_stats = []
for year in sorted(years_data.keys()):
    rates = [r['homicide_rate'] for r in years_data[year]]
    year_stats.append({
        'year': year,
        'n_countries': len(rates),
        'median': median(rates),
        'mean': mean(rates),
        'min': min(rates),
        'max': max(rates)
    })

# Most recent year
most_recent_year = max(all_years)
most_recent_data = years_data[most_recent_year]
global_median = median([r['homicide_rate'] for r in most_recent_data])

# Decade over decade change
decades = {
    '1990s': [y for y in all_years if 1990 <= y <= 1999],
    '2000s': [y for y in all_years if 2000 <= y <= 2009],
    '2010s': [y for y in all_years if 2010 <= 2019],
    '2020s': [y for y in all_years if 2020 <= y <= 2023]
}

decade_avg = {}
for decade, years in decades.items():
    rates = []
    for y in years:
        if y in years_data:
            rates.extend([r['homicide_rate'] for r in years_data[y]])
    if rates:
        decade_avg[decade] = mean(rates)

decade_changes = {}
decades_list = ['1990s', '2000s', '2010s', '2020s']
for i in range(1, len(decades_list)):
    prev = decades_list[i-1]
    curr = decades_list[i]
    if prev in decade_avg and curr in decade_avg:
        change = ((decade_avg[curr] - decade_avg[prev]) / decade_avg[prev]) * 100
        decade_changes[curr] = round(change, 1)

print("Decade averages:", {k: round(v,2) for k,v in decade_avg.items()})
print("Decade changes:", decade_changes)

# ==============================================================================
# COUNTRY-LEVEL ANALYSIS
# ==============================================================================

# Latest year per country
country_latest = {}
for r in main_data:
    country = r['country']
    if country not in country_latest or r['year'] > country_latest[country]['year']:
        country_latest[country] = r

# Sort countries by homicide rate for latest year
sorted_countries = sorted(country_latest.values(), key=lambda x: x['homicide_rate'], reverse=True)
top_10 = sorted_countries[:10]
bottom_10 = sorted_countries[-10:][::-1]

print(f"\nTop 10 countries by homicide rate:")
for c in top_10:
    print(f"  {c['country']} ({c['year']}): {c['homicide_rate']:.2f}")

print(f"\nBottom 10 countries by homicide rate:")
for c in bottom_10:
    print(f"  {c['country']} ({c['year']}): {c['homicide_rate']:.2f}")

# Highest national rate
highest_rate = max(r['homicide_rate'] for r in country_latest.values())
highest_country = [c for c in country_latest.values() if c['homicide_rate'] == highest_rate][0]

# ==============================================================================
# SEX DISPARITY ANALYSIS
# ==============================================================================

# Get male and female data for same year (both/ALL)
male_data = [r for r in data if r['sex'] == 'male' and r['age_group'] == 'ALL']
female_data = [r for r in data if r['sex'] == 'female' and r['age_group'] == 'ALL']

# Aggregate by year
male_by_year = defaultdict(list)
female_by_year = defaultdict(list)

for r in male_data:
    male_by_year[r['year']].append(r)
for r in female_data:
    female_by_year[r['year']].append(r)

# Male to female ratio over time
sex_disparity_by_year = []
for year in sorted(all_years):
    if year in male_by_year and year in female_by_year:
        male_rate = median([r['homicide_rate'] for r in male_by_year[year]])
        female_rate = median([r['homicide_rate'] for r in female_by_year[year]])
        if female_rate > 0:
            ratio = male_rate / female_rate
            sex_disparity_by_year.append({
                'year': year,
                'male_median': round(male_rate, 2),
                'female_median': round(female_rate, 2),
                'ratio': round(ratio, 2)
            })

# Most recent ratio
latest_sex = sex_disparity_by_year[-1] if sex_disparity_by_year else None
mf_ratio = latest_sex['ratio'] if latest_sex else None

# Top countries by male/female ratio (for same year, need both sexes)
country_sex = defaultdict(lambda: {'male': None, 'female': None, 'year': None})
for r in male_data:
    key = r['country']
    if country_sex[key]['male'] is None or r['year'] > country_sex[key]['year']:
        country_sex[key]['male'] = r['homicide_rate']
        country_sex[key]['year'] = r['year']

for r in female_data:
    key = r['country']
    if country_sex[key]['female'] is None:
        country_sex[key]['female'] = r['homicide_rate']
    elif r['year'] == country_sex[key]['year']:
        country_sex[key]['female'] = r['homicide_rate']

# Countries with both male and female data
mf_countries = [(k, v) for k, v in country_sex.items()
                if v['male'] is not None and v['female'] is not None and v['female'] > 0]
mf_sorted = sorted(mf_countries, key=lambda x: x[1]['male'] / x[1]['female'] if x[1]['female'] > 0 else 0, reverse=True)

print(f"\nTop 5 countries by male/female ratio:")
for c, v in mf_sorted[:5]:
    ratio = v['male'] / v['female'] if v['female'] > 0 else 0
    print(f"  {c}: M={v['male']:.2f}, F={v['female']:.2f}, ratio={ratio:.1f}x")

# ==============================================================================
# AGE GROUP ANALYSIS
# ==============================================================================

# Age group data (excluding ALL)
age_data = [r for r in data if r['age_group'] != 'ALL' and r['sex'] == 'both']

# Group by age
age_groups = defaultdict(list)
for r in age_data:
    age_groups[r['age_group']].append(r)

# Overall average by age group
age_averages = {}
for ag, records in age_groups.items():
    rates = [r['homicide_rate'] for r in records]
    age_averages[ag] = round(mean(rates), 2)

# Sort age groups
age_order = ['0-14', '15-29', '30-44', '45-59', '60+']
age_averages_sorted = {k: age_averages[k] for k in age_order if k in age_averages}

print(f"\nAge group averages:")
for k, v in age_averages_sorted.items():
    print(f"  {k}: {v:.2f}")

# ==============================================================================
# NOTABLE TRENDS - Countries with dramatic changes
# ==============================================================================

# Calculate change between first and last available year per country
country_trends = {}
for r in main_data:
    country = r['country']
    if country not in country_trends:
        country_trends[country] = []
    country_trends[country].append(r)

country_changes = []
for country, records in country_trends.items():
    if len(records) >= 2:
        records_sorted = sorted(records, key=lambda x: x['year'])
        first = records_sorted[0]
        last = records_sorted[-1]
        if first['year'] != last['year']:
            years_diff = last['year'] - first['year']
            rate_change = last['homicide_rate'] - first['homicide_rate']
            pct_change = (rate_change / first['homicide_rate']) * 100 if first['homicide_rate'] > 0 else 0
            country_changes.append({
                'country': country,
                'first_year': first['year'],
                'last_year': last['year'],
                'first_rate': first['homicide_rate'],
                'last_rate': last['homicide_rate'],
                'abs_change': round(rate_change, 2),
                'pct_change': round(pct_change, 1),
                'years': years_diff
            })

# Sort by absolute change (both increases and decreases)
improvers = sorted([c for c in country_changes if c['abs_change'] < 0], key=lambda x: x['abs_change'])
deteriorators = sorted([c for c in country_changes if c['abs_change'] > 0], key=lambda x: x['abs_change'], reverse=True)

print(f"\nTop 5 improvers (biggest decreases):")
for c in improvers[:5]:
    print(f"  {c['country']}: {c['first_rate']:.2f} -> {c['last_rate']:.2f} ({c['pct_change']}%)")

print(f"\nTop 5 deteriorators (biggest increases):")
for c in deteriorators[:5]:
    print(f"  {c['country']}: {c['first_rate']:.2f} -> {c['last_rate']:.2f} ({c['pct_change']}%)")

# ==============================================================================
# REPORTING COVERAGE
# ==============================================================================

coverage = []
for year in sorted(all_years):
    n_countries = len(set(r['country'] for r in main_data if r['year'] == year))
    coverage.append({'year': year, 'n_countries': n_countries})

print(f"\nReporting coverage: {coverage[0]['n_countries']} to {coverage[-1]['n_countries']} countries")

# ==============================================================================
# GENERATE HTML REPORT
# ==============================================================================

html = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
    :root {
        --primary: #1a365d;
        --secondary: #2c5282;
        --accent: #e53e3e;
        --success: #38a169;
        --warning: #d69e2e;
        --text: #2d3748;
        --bg: #f7fafc;
        --card-bg: #ffffff;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
        font-family: 'Segoe UI', -apple-system, sans-serif;
        background: var(--bg);
        color: var(--text);
        line-height: 1.6;
    }
    .container { max-width: 1200px; margin: 0 auto; padding: 2rem; }
    header {
        background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
        color: white;
        padding: 3rem 2rem;
        text-align: center;
    }
    header h1 { font-size: 2.5rem; margin-bottom: 0.5rem; }
    header p { opacity: 0.9; font-size: 1.1rem; }
    .kpi-dashboard {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 1.5rem;
        margin: 2rem 0;
    }
    .kpi-card {
        background: var(--card-bg);
        border-radius: 12px;
        padding: 1.5rem;
        box-shadow: 0 4px 6px rgba(0,0,0,0.07);
        border-left: 4px solid var(--primary);
    }
    .kpi-card.accent { border-left-color: var(--accent); }
    .kpi-card.success { border-left-color: var(--success); }
    .kpi-card.warning { border-left-color: var(--warning); }
    .kpi-label { font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.05em; color: #718096; margin-bottom: 0.5rem; }
    .kpi-value { font-size: 2rem; font-weight: 700; color: var(--primary); }
    .kpi-card.accent .kpi-value { color: var(--accent); }
    .kpi-card.success .kpi-value { color: var(--success); }
    .kpi-sub { font-size: 0.8rem; color: #a0aec0; margin-top: 0.25rem; }
    section {
        background: var(--card-bg);
        border-radius: 12px;
        padding: 2rem;
        margin: 2rem 0;
        box-shadow: 0 4px 6px rgba(0,0,0,0.07);
    }
    h2 { color: var(--primary); font-size: 1.5rem; margin-bottom: 1.5rem; border-bottom: 2px solid #e2e8f0; padding-bottom: 0.75rem; }
    h3 { color: var(--secondary); font-size: 1.2rem; margin: 1.5rem 0 1rem; }
    p { margin-bottom: 1rem; }
    .chart-container { position: relative; height: 400px; margin: 1.5rem 0; }
    .highlight-box {
        background: #ebf8ff;
        border-left: 4px solid var(--secondary);
        padding: 1rem;
        margin: 1rem 0;
        border-radius: 0 8px 8px 0;
    }
    .warning-box {
        background: #fffaf0;
        border-left: 4px solid var(--warning);
        padding: 1rem;
        margin: 1rem 0;
        border-radius: 0 8px 8px 0;
    }
    table { width: 100%; border-collapse: collapse; margin: 1rem 0; }
    th { background: var(--primary); color: white; padding: 0.75rem; text-align: left; }
    td { padding: 0.75rem; border-bottom: 1px solid #e2e8f0; }
    tr:hover { background: #f7fafc; }
    .trend-up { color: var(--accent); }
    .trend-down { color: var(--success); }
    footer { text-align: center; padding: 2rem; color: #718096; font-size: 0.9rem; }
    .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
    @media (max-width: 768px) { .two-col { grid-template-columns: 1fr; } }
</style>
</head>
<body>
<header>
    <h1>Global Intentional Homicide Trends</h1>
    <p>A Multi-Dimensional Analysis (1990–2023)</p>
    <p style="margin-top:1rem; font-size:0.9rem; opacity:0.8;">UNODC Crime Trends Survey Data | Policy Analyst Audience</p>
</header>
<div class="container">

<!-- KPI Dashboard -->
<div class="kpi-dashboard">
    <div class="kpi-card">
        <div class="kpi-label">Global Median Homicide Rate</div>
        <div class="kpi-value">""" + f"{global_median:.1f}" + """</div>
        <div class="kpi-sub">per 100,000 population (""" + str(most_recent_year) + """)</div>
    </div>
    <div class="kpi-card accent">
        <div class="kpi-label">Male-to-Female Ratio</div>
        <div class="kpi-value">""" + f"{mf_ratio:.1f}" + """x</div>
        <div class="kpi-sub">males per female victim</div>
    </div>
    <div class="kpi-card warning">
        <div class="kpi-label">Highest National Rate</div>
        <div class="kpi-value">""" + f"{highest_rate:.1f}" + """</div>
        <div class="kpi-sub">""" + highest_country['country'] + """ (""" + str(highest_country['year']) + """)</div>
    </div>
    <div class="kpi-card success">
        <div class="kpi-label">Decade Change (2000s→2010s)</div>
        <div class="kpi-value">""" + f"{decade_changes.get('2010s', 0):+.1f}%" + """</div>
        <div class="kpi-sub">global average shift</div>
    </div>
</div>

"""

# Section 1: Global Overview
html += """
<section id="global-overview">
    <h2>Global Homicide Rate Overview</h2>
    <p>This section presents the overall trajectory of intentional homicide rates globally from 1990 to 2023, based on reporting from <strong>""" + str(len(all_countries)) + """ countries</strong>.</p>

    <div class="highlight-box">
        <strong>Key Finding:</strong> Global median homicide rates have shown a """ + ("declining" if decade_changes.get('2010s', 0) < 0 else "increasing") + """ trend over recent decades.
        The 2000s to 2010s period saw a <strong>""" + f"{decade_changes.get('2010s', 0):+.1f}%</strong> change in the global average homicide rate.
    </div>

    <div class="chart-container">
        <canvas id="globalTrendChart"></canvas>
    </div>

    <h3>Year-by-Year Statistics</h3>
    <table>
        <tr><th>Year</th><th>Countries Reporting</th><th>Median Rate</th><th>Mean Rate</th><th>Min</th><th>Max</th></tr>
"""

for ys in year_stats[-15:]:  # Last 15 years
    html += f"        <tr><td>{ys['year']}</td><td>{ys['n_countries']}</td><td>{ys['median']:.2f}</td><td>{ys['mean']:.2f}</td><td>{ys['min']:.2f}</td><td>{ys['max']:.2f}</td></tr>\n"

html += """    </table>
</section>

<script>
new Chart(document.getElementById('globalTrendChart'), {
    type: 'line',
    data: {
        labels: """ + json.dumps([ys['year'] for ys in year_stats]) + """,
        datasets: [{
            label: 'Median Homicide Rate',
            data: """ + json.dumps([round(ys['median'], 2) for ys in year_stats]) + """,
            borderColor: '#1a365d',
            backgroundColor: 'rgba(26, 54, 93, 0.1)',
            fill: true,
            tension: 0.3
        }, {
            label: 'Mean Homicide Rate',
            data: """ + json.dumps([round(ys['mean'], 2) for ys in year_stats]) + """,
            borderColor: '#e53e3e',
            backgroundColor: 'rgba(229, 62, 62, 0.1)',
            fill: false,
            tension: 0.3
        }]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { position: 'top' } },
        scales: { y: { title: { display: true, text: 'Rate per 100,000' } } }
    }
});
