#!/usr/bin/env python3
"""
Global Intentional Homicide Trends Report Generator
Analyzes UNODC homicide data and produces a comprehensive HTML report.
"""

import csv
import json
from collections import defaultdict
from statistics import median, mean

# Load data
data = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        row['year'] = int(row['year'])
        row['homicide_rate'] = float(row['homicide_rate'])
        data.append(row)

print(f"Loaded {len(data)} rows")

# Filter helpers
def filter_data(rows, **kwargs):
    result = rows
    for key, val in kwargs.items():
        if val is not None:
            result = [r for r in result if r[key] == val]
    return result

# Get all years
all_years = sorted(set(r['year'] for r in data))
print(f"Years: {min(all_years)} - {max(all_years)}")

# Get all countries
all_countries = sorted(set(r['country'] for r in data))
print(f"Countries: {len(all_countries)}")

# Filter for sex=both and age_group=ALL for main analysis
main_data = [r for r in data if r['sex'] == 'both' and r['age_group'] == 'ALL']
print(f"Main data rows (both/ALL): {len(main_data)}")

# ==============================================================================
# GLOBAL OVERVIEW - Year-by-year statistics
# ==============================================================================

years_data = defaultdict(list)
for r in main_data:
    years_data[r['year']].append(r)

year_stats = []
for year in sorted(years_data.keys()):
    rates = [r['homicide_rate'] for r in years_data[year]]
    year_stats.append({
        'year': year,
        'n_countries': len(rates),
        'median': median(rates),
        'mean': mean(rates),
        'min': min(rates),
        'max': max(rates)
    })

# Most recent year
most_recent_year = max(all_years)
most_recent_data = years_data[most_recent_year]
global_median = median([r['homicide_rate'] for r in most_recent_data])

# Decade over decade change
decades = {
    '1990s': [y for y in all_years if 1990 <= y <= 1999],
    '2000s': [y for y in all_years if 2000 <= y <= 2009],
    '2010s': [y for y in all_years if 2010 <= 2019],
    '2020s': [y for y in all_years if 2020 <= y <= 2023]
}

decade_avg = {}
for decade, years in decades.items():
    rates = []
    for y in years:
        if y in years_data:
            rates.extend([r['homicide_rate'] for r in years_data[y]])
    if rates:
        decade_avg[decade] = mean(rates)

decade_changes = {}
decades_list = ['1990s', '2000s', '2010s', '2020s']
for i in range(1, len(decades_list)):
    prev = decades_list[i-1]
    curr = decades_list[i]
    if prev in decade_avg and curr in decade_avg:
        change = ((decade_avg[curr] - decade_avg[prev]) / decade_avg[prev]) * 100
        decade_changes[curr] = round(change, 1)

print("Decade averages:", {k: round(v,2) for k,v in decade_avg.items()})
print("Decade changes:", decade_changes)

# ==============================================================================
# COUNTRY-LEVEL ANALYSIS
# ==============================================================================

# Latest year per country
country_latest = {}
for r in main_data:
    country = r['country']
    if country not in country_latest or r['year'] > country_latest[country]['year']:
        country_latest[country] = r

# Sort countries by homicide rate for latest year
sorted_countries = sorted(country_latest.values(), key=lambda x: x['homicide_rate'], reverse=True)
top_10 = sorted_countries[:10]
bottom_10 = sorted_countries[-10:][::-1]

print(f"\nTop 10 countries by homicide rate:")
for c in top_10:
    print(f"  {c['country']} ({c['year']}): {c['homicide_rate']:.2f}")

print(f"\nBottom 10 countries by homicide rate:")
for c in bottom_10:
    print(f"  {c['country']} ({c['year']}): {c['homicide_rate']:.2f}")

# Highest national rate
highest_rate = max(r['homicide_rate'] for r in country_latest.values())
highest_country = [c for c in country_latest.values() if c['homicide_rate'] == highest_rate][0]

# ==============================================================================
# SEX DISPARITY ANALYSIS
# ==============================================================================

# Get male and female data for same year (both/ALL)
male_data = [r for r in data if r['sex'] == 'male' and r['age_group'] == 'ALL']
female_data = [r for r in data if r['sex'] == 'female' and r['age_group'] == 'ALL']

# Aggregate by year
male_by_year = defaultdict(list)
female_by_year = defaultdict(list)

for r in male_data:
    male_by_year[r['year']].append(r)
for r in female_data:
    female_by_year[r['year']].append(r)

# Male to female ratio over time
sex_disparity_by_year = []
for year in sorted(all_years):
    if year in male_by_year and year in female_by_year:
        male_rate = median([r['homicide_rate'] for r in male_by_year[year]])
        female_rate = median([r['homicide_rate'] for r in female_by_year[year]])
        if female_rate > 0:
            ratio = male_rate / female_rate
            sex_disparity_by_year.append({
                'year': year,
                'male_median': round(male_rate, 2),
                'female_median': round(female_rate, 2),
                'ratio': round(ratio, 2)
            })

# Most recent ratio
latest_sex = sex_disparity_by_year[-1] if sex_disparity_by_year else None
mf_ratio = latest_sex['ratio'] if latest_sex else None

# Top countries by male/female ratio (for same year, need both sexes)
country_sex = defaultdict(lambda: {'male': None, 'female': None, 'year': None})
for r in male_data:
    key = r['country']
    if country_sex[key]['male'] is None or r['year'] > country_sex[key]['year']:
        country_sex[key]['male'] = r['homicide_rate']
        country_sex[key]['year'] = r['year']

for r in female_data:
    key = r['country']
    if country_sex[key]['female'] is None:
        country_sex[key]['female'] = r['homicide_rate']
    elif r['year'] == country_sex[key]['year']:
        country_sex[key]['female'] = r['homicide_rate']

# Countries with both male and female data
mf_countries = [(k, v) for k, v in country_sex.items()
                if v['male'] is not None and v['female'] is not None and v['female'] > 0]
mf_sorted = sorted(mf_countries, key=lambda x: x[1]['male'] / x[1]['female'] if x[1]['female'] > 0 else 0, reverse=True)

print(f"\nTop 5 countries by male/female ratio:")
for c, v in mf_sorted[:5]:
    ratio = v['male'] / v['female'] if v['female'] > 0 else 0
    print(f"  {c}: M={v['male']:.2f}, F={v['female']:.2f}, ratio={ratio:.1f}x")

# ==============================================================================
# AGE GROUP ANALYSIS
# ==============================================================================

# Age group data (excluding ALL)
age_data = [r for r in data if r['age_group'] != 'ALL' and r['sex'] == 'both']

# Group by age
age_groups = defaultdict(list)
for r in age_data:
    age_groups[r['age_group']].append(r)

# Overall average by age group
age_averages = {}
for ag, records in age_groups.items():
    rates = [r['homicide_rate'] for r in records]
    age_averages[ag] = round(mean(rates), 2)

# Sort age groups
age_order = ['0-14', '15-29', '30-44', '45-59', '60+']
age_averages_sorted = {k: age_averages[k] for k in age_order if k in age_averages}

print(f"\nAge group averages:")
for k, v in age_averages_sorted.items():
    print(f"  {k}: {v:.2f}")

# ==============================================================================
# NOTABLE TRENDS - Countries with dramatic changes
# ==============================================================================

# Calculate change between first and last available year per country
country_trends = {}
for r in main_data:
    country = r['country']
    if country not in country_trends:
        country_trends[country] = []
    country_trends[country].append(r)

country_changes = []
for country, records in country_trends.items():
    if len(records) >= 2:
        records_sorted = sorted(records, key=lambda x: x['year'])
        first = records_sorted[0]
        last = records_sorted[-1]
        if first['year'] != last['year']:
            years_diff = last['year'] - first['year']
            rate_change = last['homicide_rate'] - first['homicide_rate']
            pct_change = (rate_change / first['homicide_rate']) * 100 if first['homicide_rate'] > 0 else 0
            country_changes.append({
                'country': country,
                'first_year': first['year'],
                'last_year': last['year'],
                'first_rate': first['homicide_rate'],
                'last_rate': last['homicide_rate'],
                'abs_change': round(rate_change, 2),
                'pct_change': round(pct_change, 1),
                'years': years_diff
            })

# Sort by absolute change (both increases and decreases)
improvers = sorted([c for c in country_changes if c['abs_change'] < 0], key=lambda x: x['abs_change'])
deteriorators = sorted([c for c in country_changes if c['abs_change'] > 0], key=lambda x: x['abs_change'], reverse=True)

print(f"\nTop 5 improvers (biggest decreases):")
for c in improvers[:5]:
    print(f"  {c['country']}: {c['first_rate']:.2f} -> {c['last_rate']:.2f} ({c['pct_change']}%)")

print(f"\nTop 5 deteriorators (biggest increases):")
for c in deteriorators[:5]:
    print(f"  {c['country']}: {c['first_rate']:.2f} -> {c['last_rate']:.2f} ({c['pct_change']}%)")

# ==============================================================================
# REPORTING COVERAGE
# ==============================================================================

coverage = []
for year in sorted(all_years):
    n_countries = len(set(r['country'] for r in main_data if r['year'] == year))
    coverage.append({'year': year, 'n_countries': n_countries})

print(f"\nReporting coverage: {coverage[0]['n_countries']} to {coverage[-1]['n_countries']} countries")

# ==============================================================================
# GENERATE HTML REPORT
# ==============================================================================

